cat > measure.js <<'EOF'
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const args = process.argv.slice(2);
  const shotDir = process.env.SHOTS || '';
  const b = await chromium.launch();
  const results = [];
  for (const spec of args) {
    const [file, w, h] = spec.split(':');
    const ctx = await b.newContext({ viewport: { width: +w, height: +h }, deviceScaleFactor: 1 });
    const p = await ctx.newPage();
    const errs = [];
    p.on('pageerror', e => errs.push(e.message.slice(0, 200)));
    p.on('console', m => { if (m.type() === 'error' && !/favicon/.test(m.text())) errs.push(m.text().slice(0, 200)); });
    await p.route('https://fonts.googleapis.com/**', r => r.fulfill({ contentType: 'text/css', body: fs.readFileSync('fonts/inter.css', 'utf8') }));
    await p.route('https://fonts.gstatic.com/**', r => r.abort());
    await p.goto('http://localhost:8765/project/' + file);
    await p.waitForTimeout(1800);
    await p.evaluate(() => document.fonts.ready);
    await p.waitForTimeout(300);
    const r = await p.evaluate(() => {
      const out = { scroll: [], spill: [] };
      const se = document.scrollingElement;
      if (se.scrollHeight > innerHeight + 1) out.scroll.push({ el: 'document', over: se.scrollHeight - innerHeight });
      for (const el of document.querySelectorAll('*')) {
        const cs = getComputedStyle(el);
        if ((cs.overflowY === 'auto' || cs.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 1 && el.clientHeight > 50) {
          out.scroll.push({ el: el.tagName.toLowerCase() + (el.id ? '#' + el.id : ''), over: el.scrollHeight - el.clientHeight });
        }
        if (['BUTTON', 'A', 'SPAN', 'LABEL', 'P', 'DD', 'DT', 'H1', 'H2', 'H3', 'LI'].includes(el.tagName) && el.scrollWidth > el.clientWidth + 1 && el.clientWidth > 0 && cs.overflowX !== 'auto') {
          out.spill.push((el.textContent || '').trim().slice(0, 40) + ' +' + (el.scrollWidth - el.clientWidth));
        }
      }
      // footer / last button bottom
      const btns = [...document.querySelectorAll('a,button')].filter(x => x.offsetParent);
      out.lowest = Math.max(0, ...btns.map(x => Math.round(x.getBoundingClientRect().bottom)));
      return out;
    });
    r.file = file; r.errs = errs;
    if (shotDir) await p.screenshot({ path: shotDir + '/' + file.replace('.dc.html', '') + '-' + w + 'x' + h + '.png' });
    results.push(r);
    await ctx.close();
  }
  await b.close();
  for (const r of results) console.log(r.file, 'scroll=' + JSON.stringify(r.scroll), r.spill.length ? 'spill=' + JSON.stringify(r.spill.slice(0, 6)) : '', r.errs.length ? 'ERR=' + JSON.stringify(r.errs.slice(0, 2)) : '');
})();
EOF
cd project && M=$(ls *-M.dc.html | sed 's/$/:390:844/'); cd .. && node measure.js $M 2>&1 | tail -40

