# Shared JS pieces injected into TopM / TopD (navigation direction, live flag, help panel, sheet drag)

NAV_CTOR = """    this.state = { help: false, closing: false, dragY: 0, dragging: false, prev: null, grown: false };
    this.drag = null;
    var dir = null, prev = null;
    try {
      dir = window.sessionStorage.getItem('lh-nav');
      prev = window.sessionStorage.getItem('lh-prog');
      window.sessionStorage.removeItem('lh-nav');
    } catch (e) {}
    try {
      var root = document.documentElement;
      root.classList.remove('nav-fwd', 'nav-back');
      if (dir === 'fwd' || dir === 'back') root.classList.add('nav-' + dir);
    } catch (e) {}
    if (dir && prev) { try { this.state.prev = JSON.parse(prev); } catch (e) {} }
    this.onDocClick = this.onDocClick.bind(this);"""

NAV_METHODS = """  componentDidMount() {
    var self = this;
    document.addEventListener('click', this.onDocClick, true);
    var raf = window.requestAnimationFrame || function (f) { return setTimeout(f, 16); };
    raf(function () { raf(function () {
      try { document.documentElement.classList.add('live'); } catch (e) {}
      if (self.state.prev) self.setState({ grown: true });
    }); });
  }
  componentWillUnmount() {
    document.removeEventListener('click', this.onDocClick, true);
    if (this.closeTimer) clearTimeout(this.closeTimer);
  }
  onDocClick(e) {
    var a = e.target && e.target.closest ? e.target.closest('a[href]') : null;
    if (!a) return;
    var href = a.getAttribute('href') || '';
    if (href === '#help') {
      e.preventDefault();
      e.stopPropagation();
      this.setState({ help: true, closing: false, dragY: 0 });
      return;
    }
    if (/\\.dc\\.html$/.test(href)) {
      var t = (a.textContent || '').trim();
      var back = a.getAttribute('data-nav') === 'back' || a.getAttribute('aria-label') === 'Back' || /^Back\\b/.test(t) || /Go back$/.test(t) || t === 'Start over' || t === 'Fix something';
      try {
        window.sessionStorage.setItem('lh-nav', back ? 'back' : 'fwd');
        if (this.progKey) window.sessionStorage.setItem('lh-prog', this.progKey);
      } catch (x) {}
    }
  }
  closeHelp() {
    var self = this;
    if (this.state.closing) return;
    this.setState({ closing: true, dragging: false });
    this.closeTimer = setTimeout(function () { self.setState({ help: false, closing: false, dragY: 0 }); }, 280);
  }"""

