from lib import write
from comps import comp

# ---------------- Dictate: grows as you type, words fade in while listening ----------------
dict_body = '''<div style="{{boxStyle}}">
  <div aria-hidden="true" ref="{{mirrorRef}}" style="{{mirrorStyle}}">{{mirrorText}}</div>
  <sc-if value="{{notListening}}" hint-placeholder-val="{{ true }}">
    <textarea aria-label="{{label}}" aria-invalid="{{invalidStr}}" aria-describedby="{{describedBy}}" placeholder="{{ph}}" value="{{text}}" onChange="{{onText}}" style="{{taStyle}}"></textarea>
  </sc-if>
  <sc-if value="{{listening}}" hint-placeholder-val="{{ false }}">
    <div role="textbox" aria-readonly="true" aria-multiline="true" aria-label="{{label}}" style="{{liveStyle}}"><sc-for list="{{words}}" as="w" hint-placeholder-count="3"><span class="w">{{w.t}}</span></sc-for><sc-if value="{{noWords}}" hint-placeholder-val="{{ true }}"><span style="color: #4F5D72">Listening… Tap to stop.</span></sc-if></div>
  </sc-if>
  <button type="button" aria-label="Speak" aria-pressed="{{listeningStr}}" onClick="{{toggle}}" style="{{micStyle}}"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"></rect><path d="M5 10a7 7 0 0 0 14 0"></path><path d="M12 17v4"></path></svg></button>
  <span role="status" style="position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap">{{status}}</span>
</div>'''

dict_script = """class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { text: props.initial ?? "I worry all the time and I've been feeling down.", listening: false, words: [], h: 0 };
    this.timer = null;
    this.mirror = null;
  }
  componentDidMount() { this.measure(); }
  componentWillUnmount() { if (this.timer) clearInterval(this.timer); }
  componentDidUpdate(prev) {
    if (prev.resetKey !== this.props.resetKey) {
      if (this.timer) clearInterval(this.timer);
      this.timer = null;
      this.setState({ text: this.props.initial ?? '', listening: false, words: [] });
      return;
    }
    this.measure();
  }
  lim() {
    var big = (this.props.size ?? 'm') === 'd';
    var pad = big ? 16 : 12;
    var minR = parseInt(this.props.minRows ?? this.props.rows ?? '2', 10) || 2;
    var maxR = parseInt(this.props.maxRows ?? '6', 10) || 6;
    return { pad: pad, min: minR * 26 + pad * 2, max: maxR * 26 + pad * 2 };
  }
  measure() {
    if (!this.mirror) return;
    var l = this.lim();
    var h = Math.max(l.min, Math.min(l.max, Math.ceil(this.mirror.scrollHeight)));
    if (Math.abs(h - this.state.h) > 0.5) this.setState({ h: h });
  }
  tell(t) { if (typeof this.props.onText === 'function') this.props.onText(t); }
  stop() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    this.setState({ listening: false });
  }
  start() {
    var self = this;
    var words = String(this.props.sample ?? "I worry all the time and I've been feeling down.").split(' ');
    var i = 0;
    this.setState({ listening: true, text: '', words: [] });
    if (this.timer) clearInterval(this.timer);
    this.timer = setInterval(function () {
      if (i >= words.length) { self.stop(); return; }
      var w = words[i];
      i += 1;
      var t = self.state.text ? self.state.text + ' ' + w : w;
      self.setState({ text: t, words: self.state.words.concat([{ t: (self.state.words.length ? ' ' : '') + w }]) });
      self.tell(t);
    }, 380);
  }
  renderVals() {
    var self = this;
    var s = this.state;
    var big = (this.props.size ?? 'm') === 'd';
    var l = this.lim();
    var invalid = (this.props.invalid ?? 'no') === 'yes';
    var h = s.h || l.min;
    var over = this.mirror ? this.mirror.scrollHeight > l.max + 1 : false;
    var border = invalid ? '2px solid #C42B2B' : (s.listening ? '2px solid #2F5FE0' : '1.5px solid #8590A2');
    var padStr = big ? '16px 72px 16px 16px' : '12px 64px 12px 16px';
    var text = 'box-sizing: border-box; width: 100%; padding: ' + padStr + '; font-family: inherit; font-size: 18px; line-height: 26px; color: #061B4D; white-space: pre-wrap; overflow-wrap: break-word; ';
    var micBase = 'position: absolute; right: 8px; bottom: 8px; display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border: 0; border-radius: 999px; cursor: pointer; ';
    return {
      label: this.props.label ?? 'What is going on?',
      describedBy: this.props.describedBy ?? '',
      text: s.text,
      mirrorText: s.text + '\\u200b',
      mirrorRef: function (el) { self.mirror = el; },
      ph: this.props.placeholder ?? 'For example: I was diagnosed with ADHD and my medication ran out.',
      status: s.listening ? 'Listening… Tap to stop.' : '',
      listening: s.listening,
      notListening: !s.listening,
      words: s.words,
      noWords: s.words.length === 0,
      listeningStr: s.listening ? 'true' : 'false',
      invalidStr: invalid ? 'true' : 'false',
      onText: function (e) { self.setState({ text: e.target.value }); self.tell(e.target.value); },
      toggle: function () { if (self.state.listening) self.stop(); else self.start(); },
      boxStyle: 'position: relative; box-sizing: border-box; width: 100%; border: ' + border + '; border-radius: 16px; background: #FFFFFF; font-family: Inter, system-ui, sans-serif; color: #061B4D; transition: border-color .3s ease',
      mirrorStyle: text + 'position: absolute; left: 0; top: 0; visibility: hidden; pointer-events: none; height: auto',
      taStyle: text + 'display: block; height: ' + h + 'px; border: 0; border-radius: 16px; outline: none; resize: none; background: transparent; overflow-y: ' + (over ? 'auto' : 'hidden') + '; transition: height .3s cubic-bezier(.22,1,.36,1)',
      liveStyle: text + 'min-height: ' + h + 'px; max-height: ' + l.max + 'px; overflow-y: auto',
      micStyle: s.listening ? micBase + 'background: #2F5FE0; color: #FFFFFF; box-shadow: 0 0 0 6px #DCE6FA' : micBase + 'background: #EEF2FC; color: #2F5FE0'
    };
  }
}"""
write('Dictate.dc.html', comp('Text box with live dictation', dict_body,
      '{"label":{"editor":"text","default":"What is going on?"},"placeholder":{"editor":"text","default":"For example: I was diagnosed with ADHD and my medication ran out."},"initial":{"editor":"text","default":"I worry all the time and I&#39;ve been feeling down."},"sample":{"editor":"text","default":"I worry all the time and I&#39;ve been feeling down."},"minRows":{"editor":"text","default":"2"},"maxRows":{"editor":"text","default":"6"},"size":{"editor":"enum","options":["m","d"],"default":"m"},"invalid":{"editor":"enum","options":["no","yes"],"default":"no"},"onText":{"editor":null},"$preview":{"width":358,"height":130}}', dict_script))

# ---------------- Availability: a provider's day strip and times ----------------
av_body = '''<div style="display: flex; flex-direction: column; gap: 8px; font-family: Inter, system-ui, sans-serif; color: #061B4D">
  <div role="radiogroup" aria-label="{{dayLabel}}" style="display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px">
    <sc-for list="{{days}}" as="d" hint-placeholder-count="3"><button type="button" role="radio" aria-checked="{{d.checked}}" aria-label="{{d.aria}}" onClick="{{d.pick}}" style="{{d.style}}"><span style="font-size: 14px; line-height: 18px; font-weight: 600; color: #4F5D72">{{d.dow}}</span><span style="font-size: 16px; line-height: 20px">{{d.date}}</span></button></sc-for>
  </div>
  <div role="radiogroup" aria-label="{{timeLabel}}" style="display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px">
    <sc-for list="{{times}}" as="t" hint-placeholder-count="3"><button type="button" role="radio" aria-checked="{{t.checked}}" aria-label="{{t.aria}}" onClick="{{t.pick}}" style="{{t.style}}">{{t.label}}</button></sc-for>
  </div>
</div>'''
av_script = """class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { day: 0, time: 0 };
  }
  data() {
    var D = {
      alex: [['Mon', 'Nov 2', 'Monday', 'November 2', ['10:00 am', '11:30 am', '2:00 pm']], ['Tue', 'Nov 3', 'Tuesday', 'November 3', ['9:00 am', '1:00 pm', '4:30 pm']], ['Wed', 'Nov 4', 'Wednesday', 'November 4', ['10:30 am', '3:00 pm']]],
      jordan: [['Tue', 'Nov 3', 'Tuesday', 'November 3', ['9:30 am', '12:00 pm']], ['Wed', 'Nov 4', 'Wednesday', 'November 4', ['8:00 am', '2:30 pm', '5:00 pm']], ['Thu', 'Nov 5', 'Thursday', 'November 5', ['10:00 am']]],
      priya: [['Wed', 'Nov 4', 'Wednesday', 'November 4', ['10:00 am', '1:30 pm']], ['Thu', 'Nov 5', 'Thursday', 'November 5', ['9:00 am', '3:30 pm']], ['Fri', 'Nov 6', 'Friday', 'November 6', ['10:00 am', '12:30 pm']]],
      sam: [['Thu', 'Nov 5', 'Thursday', 'November 5', ['11:00 am', '4:00 pm']], ['Fri', 'Nov 6', 'Friday', 'November 6', ['9:30 am']], ['Mon', 'Nov 9', 'Monday', 'November 9', ['10:00 am', '1:00 pm']]],
      taylor: [['Fri', 'Nov 6', 'Friday', 'November 6', ['8:30 am', '2:00 pm']], ['Mon', 'Nov 9', 'Monday', 'November 9', ['9:00 am', '3:30 pm']], ['Tue', 'Nov 10', 'Tuesday', 'November 10', ['11:00 am']]]
    };
    return D[this.props.who ?? 'alex'] || D.alex;
  }
  pick(day, time) {
    this.setState({ day: day, time: time });
    var d = this.data()[day];
    if (typeof this.props.onPick === 'function') this.props.onPick({ who: this.props.who ?? 'alex', day: d[2], date: d[3], short: d[0] + ', ' + d[1], time: d[4][time] });
  }
  renderVals() {
    var self = this;
    var s = this.state;
    var data = this.data();
    var name = this.props.name ?? 'Alex Rivera, PMHNP';
    var dbase = 'display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0; min-height: 52px; padding: 4px 12px; border-radius: 12px; font-family: inherit; cursor: pointer; box-sizing: border-box; ';
    var doff = dbase + 'border: 1.5px solid #8590A2; background: #FFFFFF; color: #061B4D; font-weight: 500';
    var don = dbase + 'border: 2px solid #2F5FE0; background: #EEF2FC; color: #000614; font-weight: 700';
    var tbase = 'display: flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 12px; border-radius: 999px; font-family: inherit; font-size: 16px; cursor: pointer; box-sizing: border-box; white-space: nowrap; ';
    var toff = tbase + 'border: 1.5px solid #8590A2; background: #FFFFFF; color: #061B4D; font-weight: 500';
    var ton = tbase + 'border: 2px solid #2F5FE0; background: #EEF2FC; color: #000614; font-weight: 700';
    var cur = data[s.day];
    return {
      dayLabel: 'Days with ' + name,
      timeLabel: 'Times on ' + cur[2] + ', ' + cur[3],
      days: data.map(function (d, i) {
        var on = i === s.day;
        return { dow: d[0], date: d[1], aria: d[2] + ', ' + d[3], checked: on ? 'true' : 'false', style: on ? don : doff, pick: function () { self.pick(i, 0); } };
      }),
      times: cur[4].map(function (t, j) {
        var on = j === s.time;
        return { label: t, aria: cur[2] + ', ' + cur[3] + ' at ' + t, checked: on ? 'true' : 'false', style: on ? ton : toff, pick: function () { self.pick(s.day, j); } };
      })
    };
  }
}"""
write('Availability.dc.html', comp('Provider availability', av_body,
      '{"who":{"editor":"enum","options":["alex","jordan","priya","sam","taylor"],"default":"alex"},"name":{"editor":"text","default":"Alex Rivera, PMHNP"},"onPick":{"editor":null},"$preview":{"width":326,"height":104}}', av_script))
print('comps3 ok')

