    return ('<button type="button" aria-label="See answer %d" onClick="{{openQ%d}}" style="flex: none; display: inline-flex; align-items: center; justify-content: center; min-width: 44px; min-height: 44px; margin: -10px -8px -10px 0; padding: 0 12px; border: 0; border-radius: 999px; background: %s; font-family: inherit; font-size: 14px; font-weight: 700; color: %s; cursor: pointer">%s</button>' % (n, n, bg, col, q))


def head_row(title, q, n, red=False, tag='h2'):
    col = '#8E1B1B' if red else '#4F5D72'
    fs = 'font-size: 16px; line-height: 24px; font-weight: 700' if red else 'font-size: 14px; line-height: 24px; font-weight: 600'
    icon = FLAG if red else ''
    return ('<div style="display: flex; align-items: flex-start; gap: 8px">%s<%s style="flex: 1; margin: 0; %s; color: %s">%s</%s>%s</div>' % (icon, tag, fs, col, title, tag, badge(q, n, red)))


