    facts = ('<section aria-label="From the check-in" style="display: flex; flex-direction: column; gap: 12px; padding: %s; background: #FFFFFF; border: 1px solid #E3E9F5; border-radius: 20px; box-shadow: 0 1px 2px rgba(6,27,77,0.04), 0 6px 20px rgba(6,27,77,0.06)">' % pad +
