from lib import P, FONT, write
from nav_js import NAV_CTOR, NAV_METHODS, SHEET_VALS, HELP_BODY

CHILD_HELMET = '<helmet>\n' + FONT + '\n<style>body{margin:0}</style>\n</helmet>\n'


def comp(title, body, props, script):
    return ('<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<title>%s</title>\n<script src="./support.js"></script>\n</head>\n<body>\n<x-dc>\n' % title +
            CHILD_HELMET + body + "\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script data-props='" + props + "'>\n" + script + '\n</script>\n</body>\n</html>\n')


HELP_ICON = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg>'
BTN_P = 'display: flex; align-items: center; justify-content: center; width: 100%; box-sizing: border-box; height: 54px; border: 0; border-radius: 999px; background: #2F5FE0; color: #FFFFFF; font-family: inherit; font-size: 18px; font-weight: 600; text-decoration: none; cursor: pointer'
CLOSE_X = ('<button type="button" aria-label="Close" onClick="{{closeHelp}}" style="flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; margin: -8px -8px -8px 0; border: 0; border-radius: 999px; background: transparent; color: #4F5D72; cursor: pointer">'
           '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M18 6L6 18"></path><path d="M6 6l12 12"></path></svg></button>')
DEMO_LINE = '<p style="margin: 0; text-align: center; font-size: 14px; line-height: 20px; color: #4F5D72">Demo: number and hours are made up</p>'


def logo(w, h):
    return ('<span role="img" aria-label="Legion Health" style="display: inline-flex; align-items: center; justify-content: center; width: %dpx; height: %dpx; box-sizing: border-box; border: 1px dashed #B8C2D3; border-radius: 6px; background: #F7F8FB; font-size: 14px; line-height: 20px; font-weight: 600; color: #4F5D72">Legion logo</span>' % (w, h))


# ---------------- TopM ----------------
SHEET_BASE_M = 'position: fixed; z-index: 91; left: 0; right: 0; bottom: 0; max-width: 600px; margin: 0 auto; box-sizing: border-box; display: flex; flex-direction: column; gap: 12px; padding: 0 16px calc(16px + env(safe-area-inset-bottom)); background: #FFFFFF; border-radius: 20px 20px 0 0; box-shadow: 0 -12px 40px rgba(6,27,77,0.18);'
GRAB = ('<div onPointerDown="{{dragDown}}" onPointerMove="{{dragMove}}" onPointerUp="{{dragUp}}" onPointerCancel="{{dragUp}}" style="touch-action: none; display: flex; flex-direction: column; gap: 8px; padding-top: 8px; cursor: grab">'
        '<span aria-hidden="true" style="align-self: center; width: 36px; height: 5px; border-radius: 999px; background: #C9D1DE"></span>'
        '<h2 id="help-t" class="d" style="margin: 0; font-size: 22px; line-height: 28px; font-weight: 600; color: #000614">Talk to a person</h2></div>')

topm_body = '''<div style="position: relative; z-index: 20; width: 100%; background: #FFFFFF; font-family: Inter, system-ui, sans-serif; color: #061B4D">
  <div style="background: #061B4D; color: #FFFFFF; font-size: 14px; line-height: 20px; padding: 2px 16px; text-align: center">Demo prototype: don't enter real information</div>
  <header style="max-width: 600px; margin: 0 auto; box-sizing: border-box; display: flex; align-items: center; justify-content: space-between; height: 44px; padding: 0 6px 0 16px">
    ''' + logo(112, 28) + '''
    <a href="#help" style="display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; font-size: 16px; font-weight: 600; color: #2F5FE0; text-decoration: none">''' + HELP_ICON + '''Talk to a person</a>
  </header>
  <sc-if value="{{hasProgress}}" hint-placeholder-val="{{ true }}">
    <div style="max-width: 600px; margin: 0 auto; box-sizing: border-box; display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 16px">
      <sc-if value="{{hasBack}}" hint-placeholder-val="{{ true }}">
        <a href="{{back}}" aria-label="Back" style="flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; margin: -4px -4px -4px -12px; border-radius: 999px; color: #2F5FE0"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5"></path><path d="M12 19l-7-7 7-7"></path></svg></a>
      </sc-if>
      <div role="progressbar" aria-label="{{sr}}" aria-valuetext="{{sr}}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{pct}}" style="flex: 1; display: flex; gap: 4px">
        <sc-for list="{{segs}}" as="g" hint-placeholder-count="4"><span style="flex: 1; height: 6px; border-radius: 999px; background: #E3E8F2; overflow: hidden"><span class="seg-fill" style="{{g.fill}}"></span></span></sc-for>
      </div>
    </div>
  </sc-if>
  <sc-if value="{{help}}" hint-placeholder-val="{{ false }}">
    <div class="{{backdropClass}}" aria-hidden="true" onClick="{{closeHelp}}" style="position: fixed; inset: 0; z-index: 90; background: rgba(6,27,77,0.32)"></div>
    <section role="dialog" aria-modal="true" aria-labelledby="help-t" onKeyDown="{{onKey}}" class="{{sheetClass}}" style="{{sheetStyle}}">
      ''' + GRAB + '''
      ''' + HELP_BODY + '''
      <button type="button" autoFocus="true" onClick="{{closeHelp}}" style="''' + BTN_P + '''">Close</button>
      ''' + DEMO_LINE + '''
    </section>
  </sc-if>
</div>'''

PHASE_JS = """    var p = this.props;
    var self = this;
    var s = this.state;
    var phase = p.phase ?? 'About you';
    var parts = parseInt(p.parts ?? '3', 10) || 1;
    var part = parseInt(p.part ?? '1', 10) || 1;
    var ORDER = { 'About you': 1, "What's going on": 2, 'Your provider': 3, 'Book': 4 };
    var fills = [], sr;
    if (phase === 'Check-in') {
      for (var i = 1; i <= parts; i++) fills.push(i < part ? 100 : (i === part ? 50 : 0));
      sr = 'Check-in, question ' + part + ' of ' + parts;
    } else {
      var cur = ORDER[phase] || 1;
      for (var j = 1; j <= 4; j++) fills.push(j < cur ? 100 : (j === cur ? Math.round(part / parts * 100) : 0));
      sr = phase + ', part ' + part + ' of ' + parts;
    }
    this.progKey = JSON.stringify(fills);
    var shown = fills;
    if (s.prev && !s.grown && s.prev.length === fills.length) shown = s.prev;
    var total = Math.round(fills.reduce(function (a, b) { return a + b; }, 0) / fills.length);"""

topm_script = """class Component extends DCLogic {
  constructor(props) {
    super(props);
""" + NAV_CTOR + """
  }
""" + NAV_METHODS + """
  renderVals() {
""" + PHASE_JS + """
    return {
      hasProgress: phase !== '',
      hasBack: !!(p.back ?? '#back'),
      back: p.back ?? '#back',
      sr: sr,
      pct: String(total),
      segs: shown.map(function (f) { return { fill: 'display: block; height: 100%; width: ' + f + '%; border-radius: 999px; background: #2F5FE0' }; }),
""" + SHEET_VALS.replace('SHEETCLS', 'sheet').replace('SHEETBASE ', SHEET_BASE_M + ' ') + """
    };
  }
}"""
write('TopM.dc.html', comp('Top bar · Mobile', topm_body,
      '{"back":{"editor":"text","default":"#back"},"phase":{"editor":"text","default":"About you"},"parts":{"editor":"text","default":"3"},"part":{"editor":"text","default":"1"},"$preview":{"width":390,"height":108}}', topm_script))

# ---------------- TopD ----------------
DIALOG_BASE = 'position: fixed; z-index: 91; inset: 0; margin: auto; height: fit-content; width: 440px; max-width: calc(100vw - 48px); box-sizing: border-box; display: flex; flex-direction: column; gap: 16px; padding: 24px; background: #FFFFFF; border-radius: 20px; box-shadow: 0 24px 64px rgba(6,27,77,0.24);'
topd_body = '''<div style="position: relative; z-index: 20; width: 100%; background: #FFFFFF; border-bottom: 1px solid #EEF1F6; font-family: Inter, system-ui, sans-serif; color: #061B4D">
  <div style="background: #061B4D; color: #FFFFFF; font-size: 14px; line-height: 20px; padding: 4px 16px; text-align: center">Demo prototype: don't enter real information</div>
  <header style="max-width: 1280px; margin: 0 auto; box-sizing: border-box; display: flex; align-items: center; justify-content: space-between; gap: 16px; height: 64px; padding: 0 32px">
    ''' + logo(136, 32) + '''
    <a href="#help" style="display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 8px; font-size: 16px; font-weight: 600; color: #2F5FE0; text-decoration: none">''' + HELP_ICON + '''Talk to a person</a>
  </header>
  <sc-if value="{{help}}" hint-placeholder-val="{{ false }}">
    <div class="{{backdropClass}}" aria-hidden="true" onClick="{{closeHelp}}" style="position: fixed; inset: 0; z-index: 90; background: rgba(6,27,77,0.32)"></div>
    <section role="dialog" aria-modal="true" aria-labelledby="help-t" onKeyDown="{{onKey}}" class="{{sheetClass}}" style="''' + DIALOG_BASE + '''">
      <div style="display: flex; align-items: flex-start; justify-content: space-between; gap: 16px"><h2 id="help-t" class="d" style="margin: 0; font-size: 24px; line-height: 32px; font-weight: 600; color: #000614">Talk to a person</h2>''' + CLOSE_X + '''</div>
      ''' + HELP_BODY + '''
      <button type="button" autoFocus="true" onClick="{{closeHelp}}" style="''' + BTN_P + '''">Close</button>
      ''' + DEMO_LINE + '''
    </section>
  </sc-if>
</div>'''
topd_script = """class Component extends DCLogic {
  constructor(props) {
    super(props);
""" + NAV_CTOR + """
  }
""" + NAV_METHODS + """
  renderVals() {
    var self = this;
    var s = this.state;
    this.progKey = null;
    return {
""" + SHEET_VALS.replace('SHEETCLS', 'dialog') + """
    };
  }
}"""
write('TopD.dc.html', comp('Top bar · Desktop', topd_body, '{"$preview":{"width":1440,"height":92}}', topd_script))
print('top ok')

